begin;
select set_config('qa.binder',(select id::text from public.binder_publications where is_public limit 1),true);
select set_config('qa.owner',(select user_id::text from public.binder_publications where id=current_setting('qa.binder')::uuid),true);
select set_config('qa.reporter',(select u.id::text from auth.users u where u.id<>current_setting('qa.owner')::uuid and not exists(select 1 from public.admin_accounts a where lower(u.email)=a.email and a.is_active) limit 1),true);
update public.binder_publications set hidden=false,is_listed=true where id=current_setting('qa.binder')::uuid;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('qa.owner'),'role','authenticated')::text,true);
set local role authenticated;
update public.binders set title='QA live update',revision=revision+1 where id=current_setting('qa.binder')::uuid;
do $$begin if not exists(select 1 from public.binder_publications where id=current_setting('qa.binder')::uuid and title='QA live update' and is_listed) then raise exception 'live update failed';end if;end$$;
update public.binder_publications set is_listed=false where id=current_setting('qa.binder')::uuid;
update public.binders set title='QA stopped draft',revision=revision+1 where id=current_setting('qa.binder')::uuid;
do $$begin if exists(select 1 from public.binder_publications where id=current_setting('qa.binder')::uuid and title='QA stopped draft') then raise exception 'stopped leaked';end if;end$$;
update public.binder_publications set is_listed=true where id=current_setting('qa.binder')::uuid;
update public.binders set pages='[]',revision=revision+1 where id=current_setting('qa.binder')::uuid;
do $$begin if not exists(select 1 from public.binder_publications where id=current_setting('qa.binder')::uuid and pages='[]'::jsonb) then raise exception 'empty sync failed';end if;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('qa.reporter'),'role','authenticated')::text,true);
set local role authenticated;
insert into public.community_post_reports(binder_id,reporter_user_id,reason) values(current_setting('qa.binder')::uuid,current_setting('qa.reporter')::uuid,'spam');
do $$begin
 begin insert into public.community_post_reports(binder_id,reporter_user_id,reason) values(current_setting('qa.binder')::uuid,current_setting('qa.reporter')::uuid,'other');raise exception 'duplicate allowed';exception when unique_violation then null;end;
 begin insert into public.community_post_reports(binder_id,reporter_user_id,reason) values(current_setting('qa.binder')::uuid,current_setting('qa.owner')::uuid,'other');raise exception 'spoof allowed';exception when insufficient_privilege then null;end;
end$$;
insert into public.community_user_blocks(blocker_user_id,blocked_user_id) values(current_setting('qa.reporter')::uuid,current_setting('qa.owner')::uuid) on conflict do nothing;
do $$begin if exists(select 1 from public.binder_publications where id=current_setting('qa.binder')::uuid) then raise exception 'blocked binder visible';end if;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',(select u.id from auth.users u join public.admin_accounts a on a.email=lower(u.email) where a.is_active limit 1),'role','authenticated')::text,true);
set local role authenticated;
update public.binder_publications set hidden=true where id=current_setting('qa.binder')::uuid;
do $$begin if not exists(select 1 from public.binder_publications where id=current_setting('qa.binder')::uuid and hidden) then raise exception 'admin hide failed';end if;end$$;
reset role;
select set_config('request.jwt.claims',json_build_object('sub',current_setting('qa.owner'),'role','authenticated')::text,true);
set local role authenticated;
update public.binders set title='QA hidden stays',revision=revision+1 where id=current_setting('qa.binder')::uuid;
do $$begin if not exists(select 1 from public.binder_publications where id=current_setting('qa.binder')::uuid and hidden and title='QA hidden stays') then raise exception 'hidden reset';end if;end$$;
select 'PASS live sync, stopped isolation, empty save, shared report, duplicate, spoof, block, admin moderation preserved' as result;
rollback;